sys_variable_value.value:
(function execute(inputs, outputs) {
    var rawLine = inputs.combinedLine || '';
    if (!rawLine) return;

    try {
        var columns = rawLine.split(/\|\||\|/);
        
        var cleanColumns = [];
        for (var i = 0; i < columns.length; i++) {
            var val = columns[i].trim();
            if (val !== "") {
                cleanColumns.push(val);
            }
        }

        var catItemName = cleanColumns[0] || '';
        var adGroup     = cleanColumns[1] || '';
        var license     = cleanColumns[2] || '';
        var scripted    = cleanColumns[3] || '';

        if (!catItemName) {
            // Fallback parsing just in case
            catItemName = columns[0] ? columns[0].trim() : '';
            adGroup     = columns[1] ? columns[1].trim() : '';
            license     = columns[2] ? columns[2].trim() : '';
            scripted    = columns[3] ? columns[3].trim() : '';
        }

        if (catItemName) {
            // Step 1: Query the base catalog item table where 'name' is cleanly indexed
            var catItemGr = new GlideRecord('sc_cat_item');
            catItemGr.addQuery('name', catItemName);
            catItemGr.query();
            
            if (catItemGr.next()) {
                var sysId = catItemGr.getUniqueValue();
                
                // Step 2: Grab the actual product catalog item record using its Sys ID
                var gr = new GlideRecord('pc_product_cat_item');
                if (gr.get(sysId)) {
                    var jsonPayload = {
                        "ad_group": adGroup,
                        "license_required": license,
                        "scripted": scripted
                    };

                    gr.features = JSON.stringify(jsonPayload);
                    gr.setWorkflow(false); 
                    gr.update();
                    outputs.status = "Success";
                } else {
                    outputs.status = "Error: Found in sc_cat_item but missing in pc_product_cat_item";
                }
            } else {
                outputs.status = "Error: Catalog Item name not found: " + catItemName;
            }
        }
    } catch(ex) {
        gs.error("=== EXCEL UPDATE LOG === FIELD MATCH ERROR: " + String(ex));
    }
})(inputs, outputs);

